function Get-BytesSha256 {
    param([byte[]]$Bytes)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        return ([System.BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace("-", "")
    }
    finally {
        $sha.Dispose()
    }
}

function Expand-GzipBase64 {
    param([string]$Value)
    $compressed = [System.Convert]::FromBase64String($Value)
    $input = [System.IO.MemoryStream]::new($compressed)
    $output = [System.IO.MemoryStream]::new()
    try {
        $gzip = [System.IO.Compression.GZipStream]::new(
            $input,
            [System.IO.Compression.CompressionMode]::Decompress
        )
        try { $gzip.CopyTo($output) }
        finally { $gzip.Dispose() }
        return $output.ToArray()
    }
    finally {
        $input.Dispose()
        $output.Dispose()
    }
}

function Materialize-EmbeddedFile {
    param(
        [string]$Path,
        [string]$GzipBase64,
        [string]$ExpectedSha256,
        [string]$Label
    )
    $bytes = Expand-GzipBase64 -Value $GzipBase64
    $embeddedSha = Get-BytesSha256 -Bytes $bytes
    if ($embeddedSha -ne $ExpectedSha256) {
        throw "${Label}_EMBEDDED_HASH_INVALID: actual=$embeddedSha expected=$ExpectedSha256"
    }
    if (Test-Path -LiteralPath $Path -PathType Leaf) {
        $existingSha = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
        if ($existingSha -ne $ExpectedSha256) {
            throw "${Label}_EXISTING_FILE_CONFLICT: actual=$existingSha expected=$ExpectedSha256 path=$Path"
        }
        Write-Host "${Label}_ALREADY_MATERIALIZED_PASS=$([System.IO.Path]::GetFileName($Path))"
        return
    }
    [System.IO.File]::WriteAllBytes($Path, $bytes)
    $writtenSha = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($writtenSha -ne $ExpectedSha256) {
        throw "${Label}_WRITE_HASH_INVALID: actual=$writtenSha expected=$ExpectedSha256"
    }
    Write-Host "${Label}_MATERIALIZED_PASS=$([System.IO.Path]::GetFileName($Path))"
}

function Get-LastNonEmptyLine {
    param([object[]]$Rows, [string]$FailureCode)
    $values = @(
        $Rows |
        ForEach-Object { if ($null -ne $_) { ([string]$_).Trim() } } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    )
    if ($values.Count -eq 0) { throw $FailureCode }
    return [string]$values[-1]
}

function Get-RuntimeInfo {
    param([string]$ContainerId)
    $code = "import hashlib,worker_service; p=worker_service.__file__; print(worker_service.WORKER_VERSION+'|'+p+'|'+hashlib.sha256(open(p,'rb').read()).hexdigest())"
    $rows = @(& docker exec $ContainerId python -c $code)
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_RUNTIME_INSPECTION_FAILED" }
    $line = Get-LastNonEmptyLine -Rows $rows -FailureCode "UNIFIED_RUNTIME_INSPECTION_EMPTY"
    $parts = $line.Split("|")
    if ($parts.Count -ne 3) { throw "UNIFIED_RUNTIME_INSPECTION_INVALID: $line" }
    return [pscustomobject]@{
        Version = [string]$parts[0]
        Path = [string]$parts[1]
        Sha256 = ([string]$parts[2]).ToUpperInvariant()
    }
}

function Invoke-NativeTest {
    param(
        [string]$ContainerId,
        [string[]]$Arguments,
        [string[]]$RequiredMarkers,
        [string]$FailureCode
    )
    $savedPreference = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $rows = @(& docker exec $ContainerId @Arguments 2>&1)
        $exitCode = $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $savedPreference
    }
    foreach ($row in $rows) { Write-Host ([string]$row) }
    $text = ($rows | ForEach-Object { [string]$_ }) -join "`n"
    if ($exitCode -ne 0) { throw "${FailureCode}_EXIT_${exitCode}" }
    foreach ($marker in $RequiredMarkers) {
        if (-not $text.Contains($marker)) {
            throw "${FailureCode}_MARKER_MISSING: $marker"
        }
    }
}

function Get-ProtectedTreeHash {
    param(
        [string]$ContainerId,
        [string]$HasherPath
    )
    & docker cp $HasherPath "${ContainerId}:/tmp/SM3_UNIFIED_HASH_TREE.py" | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_HASHER_COPY_FAILED" }
    $paths = @(
        "/data/media/production_state/platform_dynamics_evidence",
        "/data/media/production_state/platform_preference_signals",
        "/data/media/production_state/platform_dynamics_snapshots",
        "/data/media/production_state/platform_experiment_plans",
        "/data/media/production_state/platform_experiment_evaluations",
        "/data/media/production_state/culture_semantic_classifications",
        "/data/media/production_state/culture_semantic_consensus"
    )
    $rows = @(& docker exec $ContainerId python /tmp/SM3_UNIFIED_HASH_TREE.py @paths)
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_PROTECTED_TREE_HASH_FAILED" }
    $value = Get-LastNonEmptyLine -Rows $rows -FailureCode "UNIFIED_PROTECTED_TREE_HASH_EMPTY"
    if ($value -notmatch '^[a-f0-9]{64}$') {
        throw "UNIFIED_PROTECTED_TREE_HASH_INVALID: $value"
    }
    return $value.ToUpperInvariant()
}

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $ProjectRoot = $PSScriptRoot
}
$ProjectRoot = [System.IO.Path]::GetFullPath($ProjectRoot)

$ComposeBase = Join-Path $ProjectRoot "deployment\docker-compose.yml"
$ComposeWorker = Join-Path $ProjectRoot "deployment\docker-compose.worker.yml"
$ComposeArgs = @("-f", $ComposeBase, "-f", $ComposeWorker)
$ComposeOllama = Join-Path $ProjectRoot "deployment\docker-compose.ollama.yml"
if (Test-Path -LiteralPath $ComposeOllama -PathType Leaf) {
    $ComposeArgs += @("-f", $ComposeOllama)
}
foreach ($required in @($ComposeBase, $ComposeWorker)) {
    if (-not (Test-Path -LiteralPath $required -PathType Leaf)) {
        throw "UNIFIED_REQUIRED_FILE_NOT_FOUND: $required"
    }
}

$CandidatePath = Join-Path $ProjectRoot "SM3_worker_service_2_36_1_UNIFIED_A11_A5_A13_R2.py"
$TemporalModulePath = Join-Path $ProjectRoot "SM3_platform_temporal_validity_v1_r2.py"
$UnifiedTestPath = Join-Path $ProjectRoot "SM3_09D_A11_A5_A13_R2_UNIFIED_BEHAVIOR_TEST.py"
$TemporalTestPath = Join-Path $ProjectRoot "SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_BEHAVIOR_TEST.py"
$AdversarialTestPath = Join-Path $ProjectRoot "SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_ADVERSARIAL_ATTACK.py"
$HasherPath = Join-Path $ProjectRoot "SM3_09D_A11_A5_A13_R2_HASH_TREE.py"

Materialize-EmbeddedFile -Path $CandidatePath -GzipBase64 $CandidateGzipBase64 -ExpectedSha256 $ExpectedCandidateSha256 -Label "UNIFIED_CANDIDATE"
Materialize-EmbeddedFile -Path $TemporalModulePath -GzipBase64 $TemporalModuleGzipBase64 -ExpectedSha256 $ExpectedTemporalModuleSha256 -Label "UNIFIED_TEMPORAL_MODULE"
Materialize-EmbeddedFile -Path $UnifiedTestPath -GzipBase64 $UnifiedTestGzipBase64 -ExpectedSha256 $ExpectedUnifiedTestSha256 -Label "UNIFIED_BEHAVIOR_TEST"
Materialize-EmbeddedFile -Path $TemporalTestPath -GzipBase64 $TemporalTestGzipBase64 -ExpectedSha256 $ExpectedTemporalTestSha256 -Label "UNIFIED_TEMPORAL_TEST"
Materialize-EmbeddedFile -Path $AdversarialTestPath -GzipBase64 $AdversarialTestGzipBase64 -ExpectedSha256 $ExpectedAdversarialTestSha256 -Label "UNIFIED_ADVERSARIAL_TEST"
Materialize-EmbeddedFile -Path $HasherPath -GzipBase64 $HasherGzipBase64 -ExpectedSha256 $ExpectedHasherSha256 -Label "UNIFIED_HASHER"

$workerContainer = ""
$remoteDir = "/tmp/sm3_unified_a11_a5_a13_r2_2_36_1"
$remoteState = "/tmp/sm3_unified_a11_a5_a13_r2_state"

Push-Location $ProjectRoot
try {
    Write-Host "=== SM3 A11-A5 + A13-R2 UNIFIED 2.36.1 ISOLATED VALIDATION ==="

    $workerRows = @(& docker compose @ComposeArgs ps -q media-worker)
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_DOCKER_WORKER_PS_FAILED" }
    $workerContainer = (Get-LastNonEmptyLine -Rows $workerRows -FailureCode "UNIFIED_MEDIA_WORKER_NOT_RUNNING").Trim()

    $runtimeBefore = Get-RuntimeInfo -ContainerId $workerContainer
    $baselineAllowed = (
        ($runtimeBefore.Version -eq $ExpectedBaselineVersion -and $runtimeBefore.Sha256 -eq $ExpectedBaselineSha256) -or
        ($runtimeBefore.Version -eq $ExpectedTemporalBaselineVersion -and $runtimeBefore.Sha256 -eq $ExpectedTemporalBaselineSha256)
    )
    if (-not $baselineAllowed) {
        throw "UNIFIED_BASELINE_RUNTIME_INVALID: version=$($runtimeBefore.Version) sha256=$($runtimeBefore.Sha256)"
    }
    Write-Host "UNIFIED_BASELINE_RUNTIME_PASS=$($runtimeBefore.Version)"

    $controlBefore = Invoke-RestMethod -Uri "$ApiBaseUrl/production/culture-intelligence/runner-control" -TimeoutSec 30
    if ($controlBefore.ok -ne $true -or $null -eq $controlBefore.state) {
        throw "UNIFIED_CONTROL_RESPONSE_INVALID"
    }
    if ([string]$controlBefore.state.mode -ne "DISARMED" -or $null -ne $controlBefore.state.lease) {
        throw "UNIFIED_CONTROL_MUST_BE_DISARMED: mode=$($controlBefore.state.mode)"
    }
    Write-Host "UNIFIED_CONTROL_DISARMED_PASS"

    $protectedBefore = Get-ProtectedTreeHash -ContainerId $workerContainer -HasherPath $HasherPath
    Write-Host "UNIFIED_PROTECTED_STATE_BASELINE_PASS"

    & docker exec -u 0 $workerContainer sh -lc "rm -rf '$remoteDir' '$remoteState' && mkdir -p '$remoteDir' '$remoteState'"
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_REMOTE_SANDBOX_PREPARE_FAILED" }

    foreach ($copy in @(
        [pscustomobject]@{ Local = $CandidatePath; Remote = "$remoteDir/SM3_worker_service_2_36_1_UNIFIED_A11_A5_A13_R2.py" },
        [pscustomobject]@{ Local = $TemporalModulePath; Remote = "$remoteDir/SM3_platform_temporal_validity_v1_r2.py" },
        [pscustomobject]@{ Local = $UnifiedTestPath; Remote = "$remoteDir/SM3_09D_A11_A5_A13_R2_UNIFIED_BEHAVIOR_TEST.py" },
        [pscustomobject]@{ Local = $TemporalTestPath; Remote = "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_BEHAVIOR_TEST.py" },
        [pscustomobject]@{ Local = $AdversarialTestPath; Remote = "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_ADVERSARIAL_ATTACK.py" }
    )) {
        & docker cp $copy.Local "${workerContainer}:$($copy.Remote)" | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "UNIFIED_ARTIFACT_COPY_FAILED: $($copy.Local)" }
    }

    Invoke-NativeTest -ContainerId $workerContainer -Arguments @(
        "python", "-m", "py_compile",
        "$remoteDir/SM3_worker_service_2_36_1_UNIFIED_A11_A5_A13_R2.py",
        "$remoteDir/SM3_platform_temporal_validity_v1_r2.py",
        "$remoteDir/SM3_09D_A11_A5_A13_R2_UNIFIED_BEHAVIOR_TEST.py",
        "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_BEHAVIOR_TEST.py",
        "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_ADVERSARIAL_ATTACK.py"
    ) -RequiredMarkers @() -FailureCode "UNIFIED_COMPILE_FAILED"
    Write-Host "UNIFIED_CANDIDATE_COMPILE_PASS"

    $probeCode = "import importlib.util,sys; p='$remoteDir/SM3_worker_service_2_36_1_UNIFIED_A11_A5_A13_R2.py'; s=importlib.util.spec_from_file_location('sm3_unified',p); m=importlib.util.module_from_spec(s); sys.modules['sm3_unified']=m; s.loader.exec_module(m); print(m.WORKER_VERSION+'|'+m.TEMPORAL_VALIDITY_POLICY_VERSION+'|'+m.TEMPORAL_VALIDITY_ENGINE_VERSION+'|'+m.TEMPORAL_VALIDITY_IMPLEMENTATION_REVISION)"
    $probeRows = @(& docker exec -e "PYTHONPATH=$remoteDir" -e "MEDIA_ROOT=$remoteState" $workerContainer python -c $probeCode)
    if ($LASTEXITCODE -ne 0) { throw "UNIFIED_REAL_DEPENDENCY_IMPORT_FAILED" }
    $probe = Get-LastNonEmptyLine -Rows $probeRows -FailureCode "UNIFIED_REAL_DEPENDENCY_IMPORT_EMPTY"
    if ($probe -ne "2.36.1|SM3_PLATFORM_TEMPORAL_VALIDITY_POLICY_V1|SM3_PLATFORM_TEMPORAL_VALIDITY_ENGINE_V1|R2") {
        throw "UNIFIED_REAL_DEPENDENCY_IMPORT_INVALID: $probe"
    }
    Write-Host "UNIFIED_REAL_DEPENDENCY_IMPORT_PASS"

    Invoke-NativeTest -ContainerId $workerContainer -Arguments @(
        "python", "$remoteDir/SM3_09D_A11_A5_A13_R2_UNIFIED_BEHAVIOR_TEST.py"
    ) -RequiredMarkers @(
        "SM3_09D_A11_A5_EXPERIMENT_REGISTRY_BEHAVIOR_PASS",
        "A13_R2_TEMPORAL_API_IMPORTED=PASS",
        "REAL_NETWORK_CALLS=0",
        "REAL_MODEL_CALLS=0",
        "REAL_PRODUCTION_STATE_WRITES=0"
    ) -FailureCode "UNIFIED_A11_A5_BEHAVIOR_FAILED"
    Write-Host "UNIFIED_A11_A5_BEHAVIOR_PASS"

    Invoke-NativeTest -ContainerId $workerContainer -Arguments @(
        "python",
        "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_BEHAVIOR_TEST.py",
        "$remoteDir/SM3_platform_temporal_validity_v1_r2.py",
        "$remoteDir/temporal_behavior_report.json"
    ) -RequiredMarkers @(
        "TEST_COUNT=28",
        "PASS_COUNT=28",
        "FAILURE_COUNT=0",
        "BEHAVIOR_PASS=True",
        "NETWORK_REQUEST_PERFORMED=False",
        "MODEL_CALLED=False"
    ) -FailureCode "UNIFIED_TEMPORAL_BEHAVIOR_FAILED"
    Write-Host "UNIFIED_TEMPORAL_BEHAVIOR_PASS"

    Invoke-NativeTest -ContainerId $workerContainer -Arguments @(
        "python",
        "$remoteDir/SM3_09C7_B3E_A4_A13_R2_TEMPORAL_VALIDITY_ADVERSARIAL_ATTACK.py",
        "$remoteDir/SM3_platform_temporal_validity_v1_r2.py",
        "$remoteDir/temporal_adversarial_report.json"
    ) -RequiredMarkers @(
        "ATTACK_COUNT=21",
        "PASS_COUNT=21",
        "CRITICAL_GAP_COUNT=0",
        "HIGH_ENGINE_GAP_COUNT=0",
        "ENGINE_ATTACK_PASS=True",
        "INTEGRATION_READY=True"
    ) -FailureCode "UNIFIED_TEMPORAL_ADVERSARIAL_FAILED"
    Write-Host "UNIFIED_TEMPORAL_ADVERSARIAL_PASS"

    $runtimeAfter = Get-RuntimeInfo -ContainerId $workerContainer
    if ($runtimeAfter.Version -ne $runtimeBefore.Version -or $runtimeAfter.Sha256 -ne $runtimeBefore.Sha256) {
        throw "UNIFIED_PRODUCTION_RUNTIME_CHANGED: before=$($runtimeBefore.Version)|$($runtimeBefore.Sha256) after=$($runtimeAfter.Version)|$($runtimeAfter.Sha256)"
    }
    Write-Host "UNIFIED_PRODUCTION_RUNTIME_UNCHANGED_PASS"

    $protectedAfter = Get-ProtectedTreeHash -ContainerId $workerContainer -HasherPath $HasherPath
    if ($protectedAfter -ne $protectedBefore) {
        throw "UNIFIED_PROTECTED_STATE_CHANGED: before=$protectedBefore after=$protectedAfter"
    }
    Write-Host "UNIFIED_PROTECTED_PRODUCTION_STATE_UNCHANGED_PASS"

    $controlAfter = Invoke-RestMethod -Uri "$ApiBaseUrl/production/culture-intelligence/runner-control" -TimeoutSec 30
    if ($controlAfter.ok -ne $true -or $null -eq $controlAfter.state) {
        throw "UNIFIED_CONTROL_AFTER_RESPONSE_INVALID"
    }
    if ([string]$controlAfter.state.mode -ne "DISARMED" -or $null -ne $controlAfter.state.lease) {
        throw "UNIFIED_CONTROL_STATE_INVALID_AFTER_TEST: mode=$($controlAfter.state.mode)"
    }
    Write-Host "UNIFIED_PRODUCTION_CONTROL_REMAINED_DISARMED_PASS"

    Write-Host "SM3_09D_A11_A5_A13_R2_PREPARE_AND_VERIFY_UNIFIED_WORKER_2_36_1_PASS"
    Write-Host "BASELINE_WORKER_VERSION=$($runtimeBefore.Version)"
    Write-Host "BASELINE_RUNTIME_SHA256=$($runtimeBefore.Sha256)"
    Write-Host "CANDIDATE_WORKER_VERSION=$ExpectedCandidateVersion"
    Write-Host "CANDIDATE_SHA256=$ExpectedCandidateSha256"
    Write-Host "TEMPORAL_MODULE_SHA256=$ExpectedTemporalModuleSha256"
    Write-Host "CANDIDATE_READY=$CandidatePath"
    Write-Host "TEMPORAL_MODULE_READY=$TemporalModulePath"
    Write-Host "PRODUCTION_RUNTIME_UNCHANGED=true"
    Write-Host "PROTECTED_PRODUCTION_STATE_UNCHANGED=true"
    Write-Host "REAL_NETWORK_CALLS=0"
    Write-Host "REAL_MODEL_CALLS=0"
    Write-Host "REAL_PRODUCTION_STATE_WRITES=0"
    Write-Host "NEXT=BUILD_AND_VERIFY_A7_A8_FOR_WORKER_2_36_1"
}
finally {
    if (-not [string]::IsNullOrWhiteSpace($workerContainer)) {
        $savedPreference = $ErrorActionPreference
        $ErrorActionPreference = "Continue"
        try {
            & docker exec -u 0 $workerContainer sh -lc "rm -rf '$remoteDir' '$remoteState' /tmp/SM3_UNIFIED_HASH_TREE.py" 2>$null | Out-Null
        }
        finally {
            $ErrorActionPreference = $savedPreference
        }
    }
    Pop-Location
}
